INSERT INTO `services` (`id`, `category_id`, `name`, `slug`, `description`, `duration_minutes`, `base_price`, `icon_class`, `is_active`, `sort_order`, `created_at`, `updated_at`) VALUES (1,'cat-1','Saç Kesimi','sac-kesimi-erkek','Profesyonel saç kesimi ve stil danışmanlığı.',30,250.00,'fa-solid fa-scissors',1,1,'2026-09-23 19:51:33','2026-09-23 19:51:33'),(2,'cat-1','Sakal Tıraşı','sakal-tirasi','Klasik ustura veya makine ile sakal tıraşı ve sakal tasarımı.',15,150.00,'fa-solid fa-user',1,2,'2026-09-23 19:51:33','2026-09-23 19:51:33'),(3,'cat-1','Saç & Sakal (VIP)','sac-sakal-vip','Komple saç kesimi, sakal tıraşı, yıkama ve özel bakım.',45,350.00,'fa-solid fa-crown',1,3,'2026-09-23 19:51:33','2026-09-23 19:51:33'),(4,'cat-1','Çocuk Tıraşı','cocuk-tirasi','Çocuklara özel sabırlı ve eğlenceli saç kesimi deneyimi.',30,200.00,'fa-solid fa-child',1,4,'2026-09-23 19:51:33','2026-09-23 19:51:33'),(5,'cat-1','Damat Tıraşı','damat-tirasi','Özel gününüze yakışır VIP komple bakım paketi ve maske.',60,1000.00,'fa-solid fa-crown',1,5,'2026-09-23 19:51:33','2026-09-23 19:51:33'),(6,'cat-1','Saç Boyama (Erkek)','sac-boyama-erkek','Doğal beyaz kapatma veya modern saç renklendirme.',45,400.00,'fa-solid fa-paintbrush',1,6,'2026-09-23 19:51:33','2026-09-23 19:51:33'),(101,'cat-2','Saç Kesimi (Kadın)','sac-kesimi-kadin','Kişiye özel saç modeli kesimi ve yıkama.',45,400.00,'fa-solid fa-scissors',1,1,'2026-09-23 19:51:33','2026-09-23 19:51:33'),(102,'cat-2','Fön','fon','Düz, dalgalı veya kırık fön uygulaması.',30,200.00,'fa-solid fa-wind',1,2,'2026-09-23 19:51:33','2026-09-23 19:51:33'),(103,'cat-2','Dip Boya','dip-boya','Kaliteli profesyonel ürünlerle dip boyama işlemi.',60,500.00,'fa-solid fa-paintbrush',1,3,'2026-09-23 19:51:33','2026-09-23 19:51:33'),(104,'cat-2','Tüm Boya','tum-boya','Tüm saça renk değişimi ve homojen boya uygulaması.',90,900.00,'fa-solid fa-paintbrush',1,4,'2026-09-23 19:51:33','2026-09-23 19:51:33'),(105,'cat-2','Röfle / Ombre','rofle-ombre','Doğal geçişli ışıltı, balyaj veya modern ombre.',120,1800.00,'fa-solid fa-palette',1,5,'2026-09-23 19:51:33','2026-09-23 19:51:33'),(106,'cat-2','Manikür','manikur','El tırnak bakımı, kütikül temizliği ve oje.',30,250.00,'fa-solid fa-hand-sparkles',1,6,'2026-09-23 19:51:33','2026-09-23 19:51:33'),(107,'cat-2','Pedikür','pedikur','Ayak ve tırnak spa bakımı, topuk bakımı.',40,300.00,'fa-solid fa-shoe-prints',1,7,'2026-09-23 19:51:33','2026-09-23 19:51:33'),(108,'cat-2','Manikür + Pedikür','manikur-pedikur-kombin','Komple el ve ayak bakım paketi.',60,500.00,'fa-solid fa-hand-sparkles',1,8,'2026-09-23 19:51:33','2026-09-23 19:51:33'),(109,'cat-2','Gelin Başı','gelin-basi','Düğün gününüze özel gelin saçı tasarımı ve provası.',120,3000.00,'fa-solid fa-gem',1,9,'2026-09-23 19:51:33','2026-09-23 19:51:33'),(110,'cat-2','Makyaj (Günlük)','makyaj-gunluk','Doğal, tazeleyici ve hafif günlük makyaj uygulaması.',45,450.00,'fa-solid fa-wand-magic-sparkles',1,10,'2026-09-23 19:51:33','2026-09-23 19:51:33'),(111,'cat-2','Makyaj (Porselen)','makyaj-porselen','Gece ve özel davetler için kalıcı porselen makyaj.',60,900.00,'fa-solid fa-wand-magic-sparkles',1,11,'2026-09-23 19:51:33','2026-09-23 19:51:33'),(112,'cat-2','Ağda (Tüm Vücut)','agda-tum-vucut','Hijyenik ve profesyonel komple ağda uygulaması.',60,700.00,'fa-solid fa-leaf',1,12,'2026-09-23 19:51:33','2026-09-23 19:51:33'),(113,'cat-2','Kaş & Bıyık','kas-biyik','İp veya cımbız ile kaş tasarımı ve bıyık alımı.',15,150.00,'fa-solid fa-eye',1,13,'2026-09-23 19:51:33','2026-09-23 19:51:33');

INSERT INTO `site_contents` (`id`, `content`, `updated_by`, `created_at`, `updated_at`) VALUES (2,'{\"seo\": {\"og_title\": null, \"site_title\": \"Tarak\", \"og_image_url\": null, \"robots_index\": true, \"canonical_url\": null, \"robots_follow\": true, \"og_description\": null, \"meta_description\": \"Türkiye\'nin güvenilir berber ve kuaför platformu. Doğrulanmış uzmanlar kapına gelsin.\"}, \"home\": {\"sections\": [{\"key\": \"hero\", \"order\": 1, \"is_active\": true}, {\"key\": \"stats\", \"order\": 2, \"is_active\": true}, {\"key\": \"how_it_works\", \"order\": 3, \"is_active\": true}, {\"key\": \"categories\", \"order\": 4, \"is_active\": true}, {\"key\": \"providers\", \"order\": 5, \"is_active\": true}, {\"key\": \"verification\", \"order\": 6, \"is_active\": true}, {\"key\": \"provider_cta\", \"order\": 7, \"is_active\": true}, {\"key\": \"app_download\", \"order\": 8, \"is_active\": true}], \"providers\": {\"mode\": \"auto\", \"limit\": 8, \"title\": \"Doğrulanmış Hizmet Verenler\", \"eyebrow\": \"Öne Çıkan Uzmanlar\", \"subtitle\": \"Alanında uzman, doğrulanmış ve yüksek puanlı profesyonellerle tanışın.\"}, \"categories\": {\"limit\": 4, \"title\": \"Hizmet Kategorileri\", \"eyebrow\": \"Popüler Hizmetler\", \"subtitle\": \"İhtiyacına en uygun hizmeti seç, doğrulanmış profesyoneller kapına gelsin.\"}, \"app_download\": {\"title\": \"Tarak\", \"eyebrow\": \"Her Zaman Yanında\", \"subtitle\": \"Dilediğin yerde, dilediğin zaman. iOS ve Android uygulamalarımızla hizmetlere daha hızlı ulaş.\", \"title_highlight\": \"Cebinde!\"}, \"provider_cta\": {\"title\": \"Berber veya Kuaför olarak Aramıza Katıl\", \"eyebrow\": \"Uzman mısın?\", \"subtitle\": \"Esnek çalışma saatleri, kendi müşterilerin ve ek gelir fırsatı seni bekliyor. Binlerce kişinin bakımına dokun, güvenilir bir platformda yer al.\", \"cta_label\": \"Hemen Başvur\"}, \"verification\": {\"cards\": [{\"desc\": \"Mesleki diploma ve sertifikalar doğrulanır.\", \"icon\": \"diploma\", \"title\": \"Diploma Kontrolü\"}, {\"desc\": \"Resmi belgeler kontrol edilir.\", \"icon\": \"certificate\", \"title\": \"Kalfalık / Ustalık Belgesi\"}, {\"desc\": \"Nüfus ve kimlik bilgileri teyit edilir.\", \"icon\": \"identity\", \"title\": \"Kimlik Doğrulama\"}, {\"desc\": \"Başvuru, uzman ekibimiz tarafından manuel olarak incelenir.\", \"icon\": \"team\", \"title\": \"Uzman Ekibimiz İnceler\"}], \"title\": \"Doğrulanmış ve Güvenilir Hizmet Verenler\", \"eyebrow\": \"Güven, Bizim Standartımız\", \"subtitle\": \"Sadece yetkin, belgeli ve deneyimli profesyoneller platformumuzda yer alır. Tüm hizmet verenlerimiz, ekibimiz tarafından titizlikle incelenir ve doğrulanır.\"}}, \"legal\": {\"kvkk\": {\"body\": \"## KVKK Aydınlatma Metni\\n\\n6698 sayılı Kişisel Verilerin Korunması Kanunu (\\\"KVKK\\\") uyarınca, veri sorumlusu sıfatıyla Tarak tarafından kişisel verilerinizin işlenmesine ilişkin aşağıdaki hususlarda sizi bilgilendiririz.\\n\\n### 1. Veri Sorumlusu\\nTarak, kişisel verilerinizi KVKK kapsamında veri sorumlusu sıfatıyla işlemektedir.\\n\\n### 2. İşlenen Veriler ve Amaçları\\nKimlik, iletişim, işlem güvenliği, konum ve müşteri işlem verileriniz; hizmet sunumu, sözleşmenin ifası, yasal yükümlülükler ve meşru menfaat kapsamında işlenir.\\n\\n### 3. Verilerin Aktarımı\\nVerileriniz, hizmetin ifası için gerekli iş ortaklarına (ör. ödeme kuruluşu PayTR) ve yasal olarak yetkili kamu kurumlarına aktarılabilir.\\n\\n### 4. Veri Sahibinin Hakları\\nKVKK md. 11 uyarınca; verilerinizin işlenip işlenmediğini öğrenme, düzeltilmesini/silinmesini isteme ve işlemeye itiraz etme haklarına sahipsiniz.\\n\\n### 5. Başvuru\\nHaklarınızı kullanmak için destek@tarak.app adresine yazılı başvuruda bulunabilirsiniz.\", \"title\": \"KVKK Aydınlatma Metni\", \"updated_at\": \"2026-09-24\"}, \"terms\": {\"body\": \"## Kullanım Koşulları\\n\\nTarak\'a hoş geldiniz. Platform\'u kullanarak aşağıdaki koşulları kabul etmiş olursunuz.\\n\\n### 1. Hizmet Tanımı\\nTarak, müşteriler ile berber/kuaför hizmeti veren profesyonelleri buluşturan bir aracı platformdur. Hizmetler ilgili hizmet veren tarafından sunulur.\\n\\n### 2. Hesap ve Kullanım\\nKayıt sırasında verdiğiniz bilgilerin doğruluğundan siz sorumlusunuz. Hesabınızın güvenliğini korumak sizin sorumluluğunuzdadır.\\n\\n### 3. Ödeme ve İade\\nÖdemeler güvenli PayTR ekranı üzerinden alınır. İade süreçleri, ilgili randevu ve platform kuralları çerçevesinde yürütülür.\\n\\n### 4. Sorumluluk\\nPlatform, hizmet verenler tarafından sunulan hizmetlerin kalitesine ilişkin aracı konumundadır. Uyuşmazlıklar Platform\'un uyuşmazlık çözüm mekanizması üzerinden değerlendirilir.\\n\\n### 5. Değişiklikler\\nBu koşullar zaman zaman güncellenebilir. Güncel sürüm bu sayfada yayımlanır.\", \"title\": \"Kullanım Koşulları\", \"updated_at\": \"2026-09-24\"}, \"cookies\": {\"body\": \"## Çerez Politikası\\n\\nTarak, deneyiminizi iyileştirmek için çerezler ve benzeri teknolojiler kullanır.\\n\\n### 1. Çerez Nedir?\\nÇerezler, ziyaret ettiğiniz siteler tarafından cihazınıza kaydedilen küçük metin dosyalarıdır.\\n\\n### 2. Kullandığımız Çerezler\\n- **Zorunlu çerezler:** Oturum yönetimi ve güvenlik için gereklidir.\\n- **İşlevsel çerezler:** Tercihlerinizi (ör. dil, oturum) hatırlar.\\n\\n### 3. Çerez Yönetimi\\nTarayıcı ayarlarınızdan çerezleri yönetebilir veya silebilirsiniz. Zorunlu çerezlerin devre dışı bırakılması bazı özelliklerin çalışmamasına yol açabilir.\\n\\n### 4. İletişim\\nSorularınız için destek@tarak.app adresine ulaşabilirsiniz.\", \"title\": \"Çerez Politikası\", \"updated_at\": \"2026-09-24\"}, \"privacy\": {\"body\": \"## Gizlilik Politikası\\n\\nTarak (\\\"Platform\\\") olarak kişisel verilerinizin gizliliğine önem veriyoruz. Bu politika, Platform\'u kullanırken hangi verilerin toplandığını, nasıl işlendiğini ve haklarınızı açıklar.\\n\\n### 1. Toplanan Veriler\\n- Hesap bilgileri (ad, soyad, e-posta, telefon)\\n- Hizmet talebi ve randevu bilgileri\\n- Konum bilgisi (yalnızca hizmet eşleştirmesi ve onaylı talep sonrası, açık adres gizliliği korunarak)\\n- Ödeme işlemleri (ödemeler güvenli PayTR altyapısı üzerinden alınır; kart bilgileri Platform\'da saklanmaz)\\n\\n### 2. Verilerin Kullanım Amacı\\nVerileriniz; hizmet eşleştirmesi, randevu yönetimi, ödeme ve iade süreçleri, güvenlik ve yasal yükümlülüklerin yerine getirilmesi amacıyla işlenir.\\n\\n### 3. Verilerin Paylaşımı\\nVerileriniz, hizmetin gerçekleştirilmesi için gerekli olduğu ölçüde hizmet veren ile paylaşılır. Açık adresiniz yalnızca talebiniz onaylandıktan sonra ilgili hizmet verene iletilir.\\n\\n### 4. Veri Güvenliği\\nVerileriniz endüstri standardı güvenlik önlemleriyle korunur. Ödeme verileri PayTR tarafından işlenir.\\n\\n### 5. Haklarınız\\nKVKK kapsamındaki haklarınızı kullanmak için destek@tarak.app adresine başvurabilirsiniz.\", \"title\": \"Gizlilik Politikası\", \"updated_at\": \"2026-09-24\"}}, \"config\": {\"app_store_url\": null, \"support_email\": \"destek@tarak.app\", \"support_phone\": null, \"play_store_url\": null, \"whatsapp_number\": null}, \"social\": {\"x\": null, \"tiktok\": null, \"youtube\": null, \"facebook\": null, \"linkedin\": null, \"instagram\": null}, \"general\": {\"city\": null, \"slogan\": \"Güvenli, Profesyonel, Evinde\", \"address\": null, \"district\": null, \"site_name\": \"Tarak\", \"brand_name\": \"Tarak\", \"description\": \"Tarak, berber ve kuaför hizmetlerini güvenli, kolay ve erişilebilir hale getiren Türkiye\'nin öncü platformudur.\", \"company_name\": null, \"support_hours\": \"09:00 - 22:00\", \"working_hours\": \"09:00 - 22:00\", \"footer_description\": \"Tarak, berber ve kuaför hizmetlerini güvenli, kolay ve erişilebilir hale getiren Türkiye\'nin öncü platformudur.\"}, \"landing\": {\"hero\": {\"badge\": \"Berber ve kuaför platformu\", \"cta_primary\": \"Randevu Oluştur\", \"description\": \"Belgeleri ve kimliği kontrol edilmiş uzmanları karşılaştırın; fiyatı, süreyi ve gerçek müşteri değerlendirmelerini önceden görün, randevunuzu dakikalar içinde oluşturun.\", \"title_prefix\": \"Doğrulanmış berber ve kuaförler,\", \"cta_secondary\": \"Hizmet Veren Olarak Katıl\", \"title_highlight\": \"adresinizde.\", \"cta_primary_desc\": \"Doğrulanmış uzmanlar arasından seçin\", \"cta_secondary_desc\": \"Başvurunuz ekibimizce incelenir\"}, \"stats\": [{\"desc\": \"10.000+ değerlendirme\", \"label\": \"Ortalama Kullanıcı Puanı\", \"value\": \"4.9/5\"}, {\"desc\": \"Türkiye genelinde\", \"label\": \"Mutlu Müşteri\", \"value\": \"100.000+\"}, {\"desc\": \"Sürekli artan topluluk\", \"label\": \"Doğrulanmış Hizmet Veren\", \"value\": \"2.500+\"}, {\"desc\": \"Tüm Türkiye\'de\", \"label\": \"Hizmet Ağı\", \"value\": \"81 il\"}], \"stats_count_demo\": \"yes\", \"featured_providers\": []}, \"branding\": {\"logo_url\": null, \"favicon_url\": null, \"logo_dark_url\": null, \"hero_image_url\": null}}',1665,'2026-09-27 16:23:45','2026-10-19 13:09:57');

