-- ===========================================================================================
-- 500 TL KOMISYON / BANKA (IBAN) TAHSILATI SEMASI  (bu dosyaya eklendi, tek SQL)
--   finance_settings +5 sutun, wallets +2, provider_profiles.payment_reference (+tekil indeks), yeni tablo commission_topups,
--   migrations kaydi (2026_10_29_100000_create_commission_topups_and_gift_tracking). Yalnizca ekler; idempotent.
--   Bu bolum Laravel migration'inin birebir karsiligidir: bu dosyayi ice aktardiktan sonra `php artisan migrate --force`
--   "Nothing to migrate" der.
-- ===========================================================================================
SET NAMES utf8mb4;
SET @tarak_db = DATABASE();

-- ------------------------------------------------------------------ finance_settings
SET @s = (SELECT IF(COUNT(*) = 0, 'ALTER TABLE `finance_settings` ADD COLUMN `bank_account_holder` VARCHAR(150) COLLATE utf8mb4_unicode_ci NULL', 'DO 0') FROM information_schema.COLUMNS WHERE TABLE_SCHEMA = @tarak_db AND TABLE_NAME = 'finance_settings' AND COLUMN_NAME = 'bank_account_holder');
PREPARE st FROM @s; EXECUTE st; DEALLOCATE PREPARE st;

SET @s = (SELECT IF(COUNT(*) = 0, 'ALTER TABLE `finance_settings` ADD COLUMN `bank_name` VARCHAR(100) COLLATE utf8mb4_unicode_ci NULL', 'DO 0') FROM information_schema.COLUMNS WHERE TABLE_SCHEMA = @tarak_db AND TABLE_NAME = 'finance_settings' AND COLUMN_NAME = 'bank_name');
PREPARE st FROM @s; EXECUTE st; DEALLOCATE PREPARE st;

SET @s = (SELECT IF(COUNT(*) = 0, 'ALTER TABLE `finance_settings` ADD COLUMN `bank_iban` VARCHAR(34) COLLATE utf8mb4_unicode_ci NULL', 'DO 0') FROM information_schema.COLUMNS WHERE TABLE_SCHEMA = @tarak_db AND TABLE_NAME = 'finance_settings' AND COLUMN_NAME = 'bank_iban');
PREPARE st FROM @s; EXECUTE st; DEALLOCATE PREPARE st;

SET @s = (SELECT IF(COUNT(*) = 0, 'ALTER TABLE `finance_settings` ADD COLUMN `bank_instructions` TEXT COLLATE utf8mb4_unicode_ci NULL', 'DO 0') FROM information_schema.COLUMNS WHERE TABLE_SCHEMA = @tarak_db AND TABLE_NAME = 'finance_settings' AND COLUMN_NAME = 'bank_instructions');
PREPARE st FROM @s; EXECUTE st; DEALLOCATE PREPARE st;

SET @s = (SELECT IF(COUNT(*) = 0, 'ALTER TABLE `finance_settings` ADD COLUMN `topup_min_amount` DECIMAL(10,2) NOT NULL DEFAULT 100.00', 'DO 0') FROM information_schema.COLUMNS WHERE TABLE_SCHEMA = @tarak_db AND TABLE_NAME = 'finance_settings' AND COLUMN_NAME = 'topup_min_amount');
PREPARE st FROM @s; EXECUTE st; DEALLOCATE PREPARE st;

-- ------------------------------------------------------------------ wallets
SET @s = (SELECT IF(COUNT(*) = 0, 'ALTER TABLE `wallets` ADD COLUMN `gift_depleted_at` TIMESTAMP NULL DEFAULT NULL', 'DO 0') FROM information_schema.COLUMNS WHERE TABLE_SCHEMA = @tarak_db AND TABLE_NAME = 'wallets' AND COLUMN_NAME = 'gift_depleted_at');
PREPARE st FROM @s; EXECUTE st; DEALLOCATE PREPARE st;

SET @s = (SELECT IF(COUNT(*) = 0, 'ALTER TABLE `wallets` ADD COLUMN `gift_email_sent_at` TIMESTAMP NULL DEFAULT NULL', 'DO 0') FROM information_schema.COLUMNS WHERE TABLE_SCHEMA = @tarak_db AND TABLE_NAME = 'wallets' AND COLUMN_NAME = 'gift_email_sent_at');
PREPARE st FROM @s; EXECUTE st; DEALLOCATE PREPARE st;

-- ------------------------------------------------------------------ provider_profiles
SET @s = (SELECT IF(COUNT(*) = 0, 'ALTER TABLE `provider_profiles` ADD COLUMN `payment_reference` VARCHAR(20) COLLATE utf8mb4_unicode_ci NULL', 'DO 0') FROM information_schema.COLUMNS WHERE TABLE_SCHEMA = @tarak_db AND TABLE_NAME = 'provider_profiles' AND COLUMN_NAME = 'payment_reference');
PREPARE st FROM @s; EXECUTE st; DEALLOCATE PREPARE st;

SET @s = (SELECT IF(COUNT(*) = 0, 'ALTER TABLE `provider_profiles` ADD UNIQUE KEY `provider_profiles_payment_reference_unique` (`payment_reference`)', 'DO 0') FROM information_schema.STATISTICS WHERE TABLE_SCHEMA = @tarak_db AND TABLE_NAME = 'provider_profiles' AND INDEX_NAME = 'provider_profiles_payment_reference_unique');
PREPARE st FROM @s; EXECUTE st; DEALLOCATE PREPARE st;

-- ------------------------------------------------------------------ commission_topups
CREATE TABLE IF NOT EXISTS `commission_topups` (
  `id` bigint unsigned NOT NULL AUTO_INCREMENT,
  `provider_user_id` bigint unsigned NOT NULL,
  `reference_code` varchar(20) COLLATE utf8mb4_unicode_ci NOT NULL,
  `source` varchar(20) COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'PROVIDER_NOTICE',
  `status` varchar(20) COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'PENDING',
  `claimed_amount` decimal(12,2) NOT NULL,
  `verified_amount` decimal(12,2) DEFAULT NULL,
  `transfer_date` date DEFAULT NULL,
  `sender_name` varchar(150) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `bank_transaction_ref` varchar(100) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `provider_note` varchar(500) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `admin_note` varchar(500) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `reviewed_by_user_id` bigint unsigned DEFAULT NULL,
  `reviewed_at` timestamp NULL DEFAULT NULL,
  `wallet_transaction_id` bigint unsigned DEFAULT NULL,
  `created_at` timestamp NULL DEFAULT NULL,
  `updated_at` timestamp NULL DEFAULT NULL,
  PRIMARY KEY (`id`),
  UNIQUE KEY `commission_topups_bank_transaction_ref_unique` (`bank_transaction_ref`),
  KEY `commission_topups_reference_code_index` (`reference_code`),
  KEY `commission_topups_status_index` (`status`),
  KEY `topup_provider_status_idx` (`provider_user_id`,`status`),
  KEY `topup_status_created_idx` (`status`,`created_at`),
  KEY `commission_topups_reviewed_by_user_id_foreign` (`reviewed_by_user_id`),
  CONSTRAINT `commission_topups_provider_user_id_foreign` FOREIGN KEY (`provider_user_id`) REFERENCES `users` (`id`) ON DELETE CASCADE,
  CONSTRAINT `commission_topups_reviewed_by_user_id_foreign` FOREIGN KEY (`reviewed_by_user_id`) REFERENCES `users` (`id`) ON DELETE SET NULL
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

-- ------------------------------------------------------------------ migration kaydı
-- `php artisan migrate --force` bu migration'ı bir daha çalıştırmaz (zaten uygulanmış sayılır).
INSERT INTO `migrations` (`migration`, `batch`)
SELECT '2026_10_29_100000_create_commission_topups_and_gift_tracking', (SELECT COALESCE(MAX(`batch`), 0) + 1 FROM (SELECT `batch` FROM `migrations`) AS m)
FROM DUAL
WHERE NOT EXISTS (SELECT 1 FROM `migrations` WHERE `migration` = '2026_10_29_100000_create_commission_topups_and_gift_tracking');

